The auditor's patch is directionally correct and its addition of the analyzerLock/analyzerClosed guard is necessary (once creation is async, onCleared can race the factory and leak the native HandLandmarker). Two gaps to close: retryModelDownload() can be tapped repeatedly and start overlapping initAnalyzer() runs that leak an analyzer, and `analyzer = null` in the failure branch should be inside the lock. Corrected replacement for ScanViewModel.kt:132-179:

```kotlin
init { checkAndDownloadModel() }

private var modelJob: kotlinx.coroutines.Job? = null

private fun checkAndDownloadModel() {
    // A second tap on Retry must not race a first in-flight attempt into two analyzers.
    if (modelJob?.isActive == true) return
    modelJob = viewModelScope.launch {
        val ready = withContext(ioDispatcher) { ModelManager.isModelReady(appContext) }
        if (!ready) {
            _state.update { it.copy(modelDownloading = true, modelError = null) }
            val result = withContext(ioDispatcher) { ModelManager.downloadModel(appContext) }
            result.exceptionOrNull()?.let { t ->
                _state.update {
                    it.copy(
                        modelDownloading = false,
                        modelError = (t as? ScanErrorException)?.scanError
                            ?: ScanError.MODEL_DOWNLOAD_FAILED,
                    )
                }
                return@launch
            }
        }
        initAnalyzer()
    }
}

private suspend fun initAnalyzer() {
    val created = withContext(ioDispatcher) {
        runCatching { analyzerFactory.create(appContext, ModelManager.getModelSource(appContext)) }
    }
    created.fold(
        onSuccess = { a ->
            // onCleared may have run while the factory was on IO: close instead of leaking.
            synchronized(analyzerLock) { if (analyzerClosed) a.close() else analyzer = a }
            if (!analyzerClosed) {
                _state.update { it.copy(modelReady = true, modelDownloading = false, modelError = null) }
            }
        },
        onFailure = {
            withContext(ioDispatcher) { ModelManager.deleteDownloadedModel(appContext) }
            synchronized(analyzerLock) { analyzer = null }
            _state.update {
                it.copy(modelReady = false, modelDownloading = false, modelError = ScanError.MODEL_CORRUPT)
            }
        },
    )
}

fun retryModelDownload() { checkAndDownloadModel() }
```

